INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65018070', 65018070, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Dokumen Analisis Penguatan Pengendalian Triwulanan Kegiatan Prioritas (KP) Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 92400000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup Kegiatan untuk Jasa Konsultan Junior Penyusunan Dokumen Analisis Penguatan Pengendalian Triwulanan Kegiatan Prioritas (KP) Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo, meliputi: A. Penguatan Ex-Ante (Pengendalian Perencanaan) • Strategic Review Critical Path dan memberi rekomendasi perbaikan di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Menyusun panduan teknis pengisian exsum dan validasi data di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Merumuskan risk taxonomy di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Melakukan analisis kebutuhan dan perencanaan Dana Alokasi Khusus di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; Batasan: Jasa Konsultan Junior tidak menyusun Exsum atas nama unit kerja, mendandatangani/menetapkan dokumen. B. Penguatan On Going (Pengendalian Pelaksanaan) • Analisis Data Primer di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Menyusun catatan teknis pendampingan & rekomendasi pengendalian Analisis Data Primer di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Melakukan analisis risiko dinamis ruang lingkup Analisis Data Primer di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Melakukan analisis evaluasi pelaksanaan dan pemanfaatan Dana Alokasi Khusus Analisis Data Primer di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; • Melakukan analisis kewilayahan (spasial) pelaksanaan dan pengendalian Analisis Data Primer di Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo; Batasan: Jasa Konsultan Junior tidak menyusun Laporan Pengendalian Triwulanan resmi, dokumen formal ditetapkan oleh ASN.', 'Jasa Konsultan Junior Penyusunan Dokumen Analisis Penguatan Pengendalian Triwulanan Kegiatan Prioritas (KP) Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo dalam mendukung Pekerjaan Direktorat Pengendalian dan Evaluasi Kebijakan Strategis III memiliki keluaran setiap terminnya sebagai berikut: Periode Aktivitas Metode Output Termin 1 ● Menyusun kajian awal isu strategis dan capaian kinerja KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo berdasarkan evaluasi tahun sebelumnya ● Draf teknis awal komponen instrumen Executive Summary PN 3, termasuk pengisian contoh (dummy), kompilasi indikator risiko, dan daftar periksa validasi data sebagai bahan penyempurnaan instrument ● Melakukan analisis awal data capaian kinerja serta penyusunan draf rangkuman temuan evaluasi TW IV PN 3 KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo Literatur Review, Analisis Isu Strategis, Rapat Koordinasi, FGD, analisis data e-monev. Laporan I ● Kertas kajian isu strategis KP berbasis hasil evaluasi ● Penyiapan instrumen Temuan Executive Summary, Evaluasi TW IV dan perumusan rekomendasi debottlenecking Termin 2 ● Penyiapan fokus pengendalian TW I dalam perencanaan pembangunan nasional lingkup PN 3 Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo ● Mengidentifikasi indikasi risiko, hambatan implementasi, serta opsi mitigasi risiko dalam pelaporan e-monev TW I Rapat Koordinasi, FGD, analisis data e-monev, Literatur Review Laporan II ● Dokumen Fokus Pengendalian TW I PN 3 ● Matriks analisis risiko dan hambatan untuk pengendalian TW I Termin 3 ● Penyusunan draf rangkuman temuan evaluasi TW I Tahun 2026 lingkup PN 3 sebagai bahan teknis dalam proses koordinasi finalisasi ● Draf teknis awal SOP pengendalian triwulanan Tahun 2026 lingkup PN 3, termasuk pemetaan alur kerja, penyiapan format isian, dan kompilasi praktik eksisting ● Penajaman dan pemutakhiran Executive Summary KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo sebagai bahan teknis penyusunan Perpres RKP Rapat Koordinasi, FGD, analisis data e-monev, Literatur Review Laporan III ● finalisasi hasil pengendalian TW I ● Draf teknis awal SOP pengendalian triwulanan dan Matriks pemutakhiran Executive Summary KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo Termin 4 ● Penyusunan kertas kerja analisis awal pengendalian TW II terhadap Rancangan RKP 2027 PN 3 Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo ● Mengidentifikasi indikasi risiko, hambatan implementasi, serta opsi mitigasi risiko dalam pelaporan e-monev TW II FGD, analisis data e-monev, Literatur Review, Rapat Koordinasi Laporan IV ● Kertas kerja analisis awal pengendalian TW II ● Matriks analisis risiko dan hambatan untuk pengendalian TW II Termin 5 ● Penyusunan draf rangkuman temuan evaluasi TW II Tahun 2026 lingkup PN 3 sebagai bahan teknis dalam proses koordinasi finalisasi ● Analisis kebutuhan intervensi executive summary KP Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajo dalam penyusunan pemutakhiran RKP ● Penyusunan kertas kerja analisis awal pengendalian TW III terhadap Rancangan RKP 2027 PN 3 Rapat Koordinasi, FGD, analisis data e-monev, Literatur Review Laporan V ● finalisasi hasil pengendalian TW II dan kebutuhan intervensi ● Kertas kerja analisis awal pengendalian TW III Termin 6 ● Mengidentifikasi indikasi risiko, hambatan implementasi, serta opsi mitigasi risiko dalam pelaporan e-monev TW II ● Penyusunan draf rangkuman temuan evaluasi TW III Tahun 2026 lingkup PN 3 Bidang Percepatan Pembangunan Destinasi Pariwisata Prioritas Labuan Bajosebagai bahan teknis dalam proses koordinasi finalisasi Rapat Koordinasi, FGD, analisis data e-monev, Literatur Review Laporan VI ● Matriks analisis risiko dan hambatan untuk pengendalian TW III ● finalisasi hasil pengendalian dan evaluasi TW III Keterangan: Metode pelaksanaan pekerjaan mengikuti kegiatan Unit Kerja yang bersangkutan, sehingga pembiayaan atas pelaksanaan beberapa aktivitas seperti/dan tidak terbatas pada pelaksanaan rapat, FGD, observasi lapangan, perjalanan dinas lainnya tidak termasuk dalam komponen harga jasa konsultansi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 464514);
