INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62409180', 62409180, 'analyze_legacy', 'Kementerian Agama', 'central', 'UIN Raden Mas Said Surakarta 547601', 'RM - TIPD - Bandwith Layanan pendidikan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Tengah, Sukoharjo (Kab.)', 2000000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '12 bulan', 'Pengadaan langganan internet selama 1 tahun.', 'Layanan IP Transit Internasional/Domestik 2Gbps. Bandwith Utama NAP DC UIN minimal bandwith 2000 mbps. Layanan tambahan: • Koneksi Internet Dedicated FO atau metro-E Gd. Pascasarjana di Pakis Kab. Klaten minimal 500 mbps minimal 1 IP Public. • Memiliki Kabel Sendiri (Diutamakan). • Menyediakan Network Monitoring System dan Trouble Shoot secara transparan dan realtime. • Kantor perwakilan di wilayah Surakarta / EOS (enginer on site) yang aktif selama 7 x 24 jam. • Pengalaman penyediaan bandwidth internet dengan kapasitas 2 – 10 Gbps • Terdaftar di ekatalog lkpp/inaproc sebagai penyedia layanan internet. • Kesanggupan pengecekan dan perbaikan jalur Fiber Optik Gedung ABCDEF, FAB, FUD, GLM, Gd. B. Pasca Pakis, Gd. Admisi serta menyediakan peralatan distribusi pada tersebut sesuai dengan hasil survey meliputi akses point dual band dan switch sesuai kebutuhan sejumlah 50 unit AP (minimal Unifi AC Pro Indoor) dan 3 switch layer 3 dengan POE* (minimal mikrotik CSR 24Port + SFP10G) dan akan dihibahkan ke UIN setelah masa kontrak berakhir. • Kesanggupan untuk meminjamkan peralatan Router/switch (switch BGP/Backbone) distribusi sejenis bila peralatan distribusi mengalami kendala. • Sanggup melakukan audit dan survey terhadap sarana-prasarana layanan IT di UIN Raden Mas Said Surakarta per semester. • Kesanggupan untuk aktivasi Service nomor 1 ,mulai tanggal 02 Januari 2026 pukul 00.00 WIB, sedangkan lainnya maksimal 3 minggu setelah kontrak berlaku. • Koneksi layer 2 - lease line ke GGC UNY IX sebesar minimal 500 mbps dengan fiber optik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 465980);
