INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63020009', 63020009, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PERTANIAN', '5.1.02.01.001.00008 - Belanja Bahan-Bahan/Bibit Tanaman', 'Barang', 'Pengadaan Langsung', 'Jawa Barat, Bandung (Kab.)', 18785000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Perencanaan dan persiapan pengadaan. Pengadaan benih padi Inpari Pengadaan benih kentang G2 varietas Granola. Pengadaan planlet kentang hasil kultur jaringan. Pemeriksaan mutu dan spesifikasi teknis. Pengemasan, pengangkutan, dan penyerahan. Pelaporan hasil kegiatan.', '1. Benih Padi, 630 Kg Komoditas: Padi Varietas: Inpari Kelas benih: Benih bersertifikat Daya kecambah: Minimal 80%. Kadar air: Sesuai standar perbenihan. Kemurnian fisik dan genetik terjamin. Bebas dari hama dan penyakit. Dikemas dan diberi label resmi. 2. Benih Kentang G2 Varietas Granola, 100 Kg Komoditas: Kentang (Solanum tuberosum L.). Varietas: Granola. Kelas benih: G2, Ukuran umbi: Seragam dan sesuai standar benih. Kondisi umbi: Sehat, tidak luka, tidak busuk, tidak bertunas berlebihan. Bebas dari organisme pengganggu tanaman. Berasal dari produsen benih resmi dan bersertifikat. 3. Planlet Kentang, 50 Botol Komoditas: Kentang (Solanum tuberosum L.). Asal planlet: Laboratorium kultur jaringan yang kompeten. Kondisi planlet: Sehat, vigor baik, bebas kontaminasi. Umur planlet: Siap sub kultur dan aklimatisasi Media kultur: Steril dan sesuai standar kultur jaringan. Varietas: Granola', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 469372);
